use std::{collections::{BTreeMap,BTreeSet},fs};use serde_json::{json,Value};use zopro_bn254::Fr;use zopro_prover::zopro_core::artifact::Artifact;
#[global_allocator]static ALLOCATOR:zopro_prover::zopro_core::alloc::Allocator=zopro_prover::zopro_core::alloc::Allocator;
mod model;mod split;type Word=[u64;4];
fn groups(words:&[Word])->Option<(Vec<Word>,Vec<usize>)>{let n=words.len();if n<256{return None}let sample=n.min(2048);let stride=n.div_ceil(sample);let seen=words.iter().step_by(stride).take(sample).collect::<BTreeSet<_>>();let observed=n.div_ceil(stride).min(sample);if seen.len()*200>observed*199{return None}let percent=if(32768..65536).contains(&n){95}else{80};let zeros=words.iter().step_by(stride).take(sample).filter(|s|**s==[0;4]).count();let nonzero=observed-zeros;if seen.len()-usize::from(zeros!=0)==nonzero&&nonzero*100>observed*percent{return None}let mut map=BTreeMap::new();let mut values=vec![];let mut classes=vec![usize::MAX;n];for(i,&v)in words.iter().enumerate(){if v==[0;4]{continue}let class=*map.entry(v).or_insert_with(||{values.push(v);values.len()-1});classes[i]=class;}if values.len()*100>n*percent{None}else{Some((values,classes))}}
fn signed_component(s:&Word,high:bool)->Fr{let i=usize::from(high)*2;let bytes=[s[i],s[i+1]&0x7fffffffffffffff].into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>();let v=Fr::from_le_bytes_mod_order(&bytes);if s[i+1]>>63!=0{-v}else{v}}
fn token(seed:&mut u64)->Fr{let mut b=[0;32];for c in b.chunks_mut(8){*seed^=*seed<<13;*seed^=*seed>>7;*seed^=*seed<<17;c.copy_from_slice(&seed.to_le_bytes());}Fr::from_le_bytes_mod_order(&b)}
fn aggregate(rows:&[Value],scan:bool)->Value{let mut sums=BTreeMap::<String,usize>::new();let mut hist=BTreeMap::<String,usize>::new();for row in rows{let c=&row[if scan{"scan"}else{"lifo"}];for(k,v)in c.as_object().unwrap(){if k=="batch_histogram"{for(k,v)in v.as_object().unwrap(){*hist.entry(k.clone()).or_default()+=v.as_u64().unwrap()as usize;}}else{let n=v.as_u64().unwrap()as usize;let s=sums.entry(k.clone()).or_default();if k=="max_batch"||k=="max_queue"{*s=(*s).max(n)}else{*s+=n}}}}let mut v=json!(sums);v["batch_histogram"]=json!(hist);v}
fn census(words:&[Word],mapping:Option<&[usize]>,original_n:usize)->Value{let short=words.iter().map(|&v|split::phi_split(v)).collect::<Vec<_>>();let lambda=split::phi_lambda();assert_ne!(lambda,Fr::ONE);assert_eq!(lambda*lambda*lambda,Fr::ONE);
 for(s,w)in short.iter().zip(words){assert_eq!(signed_component(s,false)+lambda*signed_component(s,true),Fr::from_le_bytes_mod_order(&w.into_iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()));for high in[false,true]{let mut value=Fr::ZERO;let mut power=Fr::ONE;for window in 0..11{let d=split::digit_of(s,high,window,12)as i32;let v=Fr::from(d.unsigned_abs()as u64);value+=power*if d<0{-v}else{v};power*=Fr::from(4096u64);}assert_eq!(value,signed_component(s,high));}}
 let mut rows=vec![];let chunk=words.len().div_ceil(2);for w in 0..10{for part in 0..2{let start=(part*chunk).min(words.len());let end=(start+chunk).min(words.len());let mut checked=None;for seed_tag in 0..2{let mut seed=0x7175657565736361u64^(seed_tag as u64*1597);let original=(0..original_n).map(|_|token(&mut seed)).collect::<Vec<_>>();let tokens=if let Some(classes)=mapping{let mut t=vec![Fr::ZERO;words.len()];for(&c,v)in classes.iter().zip(original){if c!=usize::MAX{t[c]+=v;}}t}else{original};let mut a=model::Model::new(2048,200,false);let mut b=model::Model::new(2048,200,true);let mut expected=vec![Fr::ZERO;2048];for high in[true,false]{let arrivals=(start..end).filter_map(|i|{let d=split::digit_of(&short[i],high,w,12);if d==0{return None}let bucket=d.unsigned_abs()as u32-1;let encoded=bucket|if d<0{1<<31}else{0};expected[bucket as usize]+=if d<0{-tokens[i]}else{tokens[i]};Some((encoded,tokens[i]))}).collect::<Vec<_>>();a.feed(&arrivals);b.feed(&arrivals);if high{a.phi(lambda);b.phi(lambda);for v in &mut expected{*v*=lambda;}}}let(x,ca)=a.finish();let(y,cb)=b.finish();assert_eq!(x,expected);assert_eq!(y,expected);assert!(ca.max_batch<=200&&cb.max_batch<=200&&ca.max_queue<200&&cb.max_queue<200);let counts=json!({"window":w,"part":part,"input_rows":end-start,"lifo":ca.json(),"scan":cb.json(),"every_bucket_oracle_checked":true,"ordinary_noncancelling_model":true});if let Some(previous)=&checked{assert_eq!(*previous,counts);}else{checked=Some(counts);}}rows.push(checked.unwrap());}}
 let a=aggregate(&rows,false);let b=aggregate(&rows,true);let saved=a["projective_arrivals"].as_i64().unwrap()-b["projective_arrivals"].as_i64().unwrap();let inv=b["batches"].as_i64().unwrap()-a["batches"].as_i64().unwrap();json!({"modeled_scalar_terms":words.len(),"ordinary_window_parts":20,"two_independent_token_streams":true,"all_Phi_and_Booth_reconstructions_exact":true,"all_buckets_equal_direct_oracle":true,"lifo":a,"scan":b,"projective_arrivals_avoided":saved,"extra_batch_inversions":inv,"rows":rows})}
fn main(){let cases:Value=serde_json::from_slice(&fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let mut output=vec![];for case in cases.as_array().unwrap().iter().take(2){let bytes=fs::read(case["key"].as_str().unwrap()).unwrap();let request=fs::read_to_string(case["request"].as_str().unwrap()).unwrap();let sdk=zopro_zolana::Prover::load(&bytes).unwrap();let witness=sdk.witness(&request).unwrap();let image=sdk.solver_image().unwrap();drop(sdk);let artifact=Artifact::parse(&bytes).unwrap();let key=artifact.key(artifact.points(),Some(&image)).unwrap();let witness:Vec<_>=witness.iter().flat_map(|v|v.0.iter().flat_map(|v|v.to_le_bytes())).collect();let v=key.msm_scalars(&witness).unwrap();let words=v[1].iter().map(Fr::to_canonical).collect::<Vec<_>>();assert!((1024..65536).contains(&words.len()));let grouped=groups(&words);let mut c=if let Some((values,classes))=&grouped{census(values,Some(classes),words.len())}else{census(&words,None,words.len())};c["shape"]=case["shape"].clone();c["original_B_rows"]=json!(words.len());c["grouping_admitted"]=json!(grouped.is_some());c["new_solver_calls"]=json!(1);println!("ROW {}",c);output.push(c);}let pass=output[0]["projective_arrivals_avoided"].as_i64().unwrap()>0;println!("COMPLETE {}",json!({"necessary_opportunity_gate":pass,"real_shapes":2,"new_solver_calls":2,"new_SDK_requests":0,"new_independent_exports":0,"proof_ledger":23971,"production_changed":false,"performance_claim":false,"requires_valid_curve_and_SDK_qualification":true}));}
